namespace MhwModManager.Core;

/// <summary>
/// Presentation-only cleanup of the SHA-256 receipt suffix on auto-sorted
/// package folders. Never use the cleaned label as a package identity, a
/// deduplication key, or authorization to change source files.
/// </summary>
public static class ModDisplayNames
{
    public static string StripTransportDigest(string name)
    {
        using var __mhwTrace = MasterDebugLog.BeginMethod();
        if (string.IsNullOrEmpty(name)) return name;
        var end = name.Length;
        // Preserve the collision suffix generated by Inbox publication.
        var copyStart = name.LastIndexOf(" (", StringComparison.Ordinal);
        if (copyStart > 0 && name.EndsWith(')') &&
            name.AsSpan(copyStart + 2, name.Length - copyStart - 3).ToString()
                .All(char.IsAsciiDigit))
            end = copyStart;
        var digestStart = end - 65;
        if (digestStart <= 0 || name[digestStart] != '-') return name;
        var digest = name.AsSpan(digestStart + 1, 64);
        if (!digest.ToString().All(Uri.IsHexDigit)) return name;
        return name[..digestStart] + name[end..];
    }
}
